// Helpers for reading the Task 2b data files.
//
// DO NOT EDIT THIS FILE. The marking harness replaces it with its own copy.
// You are welcome to use it from your own code (e.g. src/main.cpp).
#pragma once

#include <cstdint>
#include <fstream>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

#include "challenge.hpp"

namespace challenge_io {

// Directory of the repository root, set by CMake.
#ifdef CHALLENGE_REPO_ROOT
inline const std::string kRepoRoot = CHALLENGE_REPO_ROOT;
#else
inline const std::string kRepoRoot = ".";
#endif
inline const std::string kDataDir = kRepoRoot + "/data";
inline const std::string kOutputDir = kRepoRoot + "/output";

inline std::vector<std::string> split_csv_line(const std::string& line) {
    std::vector<std::string> out;
    std::stringstream ss(line);
    std::string cell;
    while (std::getline(ss, cell, ',')) {
        if (!cell.empty() && cell.back() == '\r') cell.pop_back();
        out.push_back(cell);
    }
    return out;
}

// Rows of a CSV file, header skipped.
inline std::vector<std::vector<std::string>> read_csv_rows(const std::string& path) {
    std::ifstream f(path);
    if (!f) throw std::runtime_error("cannot open " + path);
    std::vector<std::vector<std::string>> rows;
    std::string line;
    std::getline(f, line);  // header
    while (std::getline(f, line)) {
        if (!line.empty() && line != "\r") rows.push_back(split_csv_line(line));
    }
    return rows;
}

// trajectory.csv as {timestamp_ms: pose}.
inline std::map<std::int64_t, Pose> load_trajectory(const std::string& path) {
    std::map<std::int64_t, Pose> poses;
    for (const auto& r : read_csv_rows(path)) {
        poses[std::stoll(r.at(0))] = Pose{std::stod(r.at(1)), std::stod(r.at(2)), std::stod(r.at(3))};
    }
    return poses;
}

// frames.csv as a list of timestamps (ms).
inline std::vector<std::int64_t> load_frames(const std::string& path) {
    std::vector<std::int64_t> frames;
    for (const auto& r : read_csv_rows(path)) frames.push_back(std::stoll(r.at(0)));
    return frames;
}

// Minimal reader for the flat numeric keys in camera.json.
inline double json_number(const std::string& text, const std::string& key) {
    auto k = text.find("\"" + key + "\"");
    if (k == std::string::npos) throw std::runtime_error("camera.json: missing key " + key);
    auto colon = text.find(':', k);
    return std::stod(text.substr(colon + 1));
}

inline Camera load_camera(const std::string& path) {
    std::ifstream f(path);
    if (!f) throw std::runtime_error("cannot open " + path);
    std::stringstream ss;
    ss << f.rdbuf();
    const std::string t = ss.str();
    Camera c{};
    c.image_width = static_cast<int>(json_number(t, "image_width"));
    c.image_height = static_cast<int>(json_number(t, "image_height"));
    c.fx = json_number(t, "fx");
    c.fy = json_number(t, "fy");
    c.cx = json_number(t, "cx");
    c.cy = json_number(t, "cy");
    c.mount.forward_offset_m = json_number(t, "forward_offset_m");
    c.mount.height_m = json_number(t, "height_m");
    c.mount.pitch_rad = json_number(t, "pitch_rad");
    return c;
}

}  // namespace challenge_io
